def solve(nums, target):
    def binary_search(left, right):
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                return mid
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    n = len(nums)
    if n == 0:
        return [-1, -1]

    # Step 1: Exponential search to find a boundary
    bound = 1
    while bound < n and nums[bound] < target:
        bound *= 2

    # Step 2: Binary search between [n//2, bound]
    left, right = max(0, bound // 2), min(n - 1, bound)
    idx = binary_search(left, right)

    if idx == -1:
        return [-1, -1]

    # Step 3: Find first occurrence
    first = idx
    while first > 0 and nums[first - 1] == target:
        first -= 1

    # Step 4: Find last occurrence
    last = idx
    while last < n - 1 and nums[last + 1] == target:
        last += 1

    return [first, last]

